// Tree-sitter grammar for kif (docs/kif-proc-language.md).
// This is a lexical grammar ("token soup"): it recognises comments, strings, numbers, attributes, lifetimes, raw blocks
// and a few declaration names, which is all highlighting and injection need; the real parser is kiflang/parser.py.
// The word lists between the GEN markers are generated by kif-editor/gen_syntax.py.
/// <reference types="tree-sitter-cli/dsl" />
// @ts-check

module.exports = grammar({
  name: 'kif',

  word: $ => $.identifier,
  extras: $ => [/\s/, $.comment],
  externals: $ => [$.verbatim_body],

  rules: {
    source_file: $ => repeat($._item),

    _item: $ => choice(
      $.verbatim_block,
      $.attribute,
      $.declaration,
      $.macro_call,
      $.string,
      $.number,
      $.lifetime,
      $.keyword,
      $.verbatim_word,
      $.identifier,
      $.punctuation,
    ),

    comment: _ => token(seq('//', /[^\n]*/)),

    // header(c) { ... } / code(cxx) { ... } / m_prolog { ... }; the body ends at a '}' alone on a line
    verbatim_block: $ => prec(2, seq(
      $.verbatim_word,
      optional(seq('(', field('tag', $.identifier), ')')),
      '{',
      optional($.verbatim_body),
      '}',
    )),

    attribute: $ => seq(choice('#[', '#!['), repeat(choice($.string, $.number, $.identifier, $.punctuation)), ']'),

    declaration: $ => prec(2, seq(
      choice('interface', 'struct', 'enum', 'type', 'impl', 'fn', 'method', 'macro', 'const', 'namespace'),
      field('name', $.identifier),
    )),

    macro_call: $ => prec(2, seq(field('name', $.identifier), token.immediate('!'))),

    string: _ => token(seq('"', repeat(choice(/[^"\\\n]/, /\\./)), '"')),
    number: _ => token(/(0[xX][0-9a-fA-F_]+|0[bB][01_]+|0[oO][0-7_]+|[0-9][0-9_]*)([iu](8|16|32|64|size))?/),
    lifetime: _ => token(/'[A-Za-z_][A-Za-z0-9_]*/),
    identifier: _ => /[A-Za-z_][A-Za-z0-9_]*/,
    punctuation: _ => token(choice(/[-+*\/%&|^!<>=?:;,.@~]+/, '(', ')', '[', ']', '{', '}')),

// GEN-BEGIN words
    keyword: _ => choice(
      'as', 'break', 'cfg', 'const', 'continue', 'else', 'enum', 'export', 'extern', 'fn', 'for',
      'gen', 'if', 'impl', 'in', 'let', 'loop', 'macro', 'match', 'mut', 'private', 'return',
      'struct', 'type', 'unsafe', 'use', 'while',
    ),
    verbatim_word: _ => choice('header', 'code', 'm_prolog', 'm_epilog'),
// GEN-END words
  },
});
